import re
import sys

_TOKEN = re.compile(
    r"\s*(<=|>=|<>|SUM|MIN|MAX|IF|[A-Z][1-9][0-9]?|\d+|[+*/(),:<>=-])"
)


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    if sys.getrecursionlimit() < 20000:
        sys.setrecursionlimit(20000)

    memo: dict[str, int | str] = {}
    visiting: set[str] = set()

    def expand(a: str, b: str):
        c1, r1 = ord(a[0]) - 65, int(a[1:])
        c2, r2 = ord(b[0]) - 65, int(b[1:])
        if c1 > c2:
            c1, c2 = c2, c1
        if r1 > r2:
            r1, r2 = r2, r1
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                yield chr(65 + c) + str(r)

    def parse(s: str):
        toks = _TOKEN.findall(s)
        i = 0

        def peek():
            return toks[i] if i < len(toks) else None

        def pop():
            nonlocal i
            t = toks[i]
            i += 1
            return t

        def parse_expr():
            node = parse_term()
            while peek() in ("+", "-"):
                op = pop()
                node = ("bin", op, node, parse_term())
            return node

        def parse_term():
            node = parse_unary()
            while peek() in ("*", "/"):
                op = pop()
                node = ("bin", op, node, parse_unary())
            return node

        def parse_unary():
            if peek() == "-":
                pop()
                return ("neg", parse_unary())
            return parse_atom()

        def parse_atom():
            t = peek()
            if t == "(":
                pop()
                node = parse_expr()
                pop()
                return node
            if t in ("SUM", "MIN", "MAX"):
                return parse_agg()
            if t == "IF":
                return parse_if()
            pop()
            if t[0].isdigit():
                return ("num", int(t))
            return ("cell", t)

        def parse_arg():
            t = peek()
            if (
                t is not None
                and t[0].isalpha()
                and t not in ("SUM", "MIN", "MAX", "IF")
                and i + 1 < len(toks)
                and toks[i + 1] == ":"
            ):
                a = pop()
                pop()
                b = pop()
                return ("range", a, b)
            return parse_expr()

        def parse_agg():
            fn = pop()
            pop()
            args = [parse_arg()]
            while peek() == ",":
                pop()
                args.append(parse_arg())
            pop()
            return ("agg", fn, args)

        def parse_if():
            pop()
            pop()
            left = parse_expr()
            op = pop()
            right = parse_expr()
            pop()
            then_n = parse_expr()
            pop()
            else_n = parse_expr()
            pop()
            return ("if", op, left, right, then_n, else_n)

        return parse_expr()

    def eval_cell(name: str):
        if name in memo:
            return memo[name]
        if name not in cells:
            return 0
        if name in visiting:
            return "#CYCLE!"
        visiting.add(name)
        raw = cells[name].strip()
        if raw.startswith("="):
            val = ev(parse(raw[1:]))
        else:
            val = int(raw)
        visiting.remove(name)
        memo[name] = val
        return val

    def ev(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "cell":
            return eval_cell(node[1])
        if kind == "neg":
            v = ev(node[1])
            return v if isinstance(v, str) else -v
        if kind == "bin":
            op, left, right = node[1], node[2], node[3]
            a = ev(left)
            if isinstance(a, str):
                return a
            b = ev(right)
            if isinstance(b, str):
                return b
            if op == "+":
                return a + b
            if op == "-":
                return a - b
            if op == "*":
                return a * b
            if b == 0:
                return "#DIV/0!"
            sign = -1 if (a < 0) ^ (b < 0) else 1
            return sign * (abs(a) // abs(b))
        if kind == "if":
            op, left, right, then_n, else_n = node[1], node[2], node[3], node[4], node[5]
            a = ev(left)
            if isinstance(a, str):
                return a
            b = ev(right)
            if isinstance(b, str):
                return b
            if op == "=":
                cond = a == b
            elif op == "<>":
                cond = a != b
            elif op == "<":
                cond = a < b
            elif op == "<=":
                cond = a <= b
            elif op == ">":
                cond = a > b
            else:
                cond = a >= b
            return ev(then_n if cond else else_n)
        fn, args = node[1], node[2]
        vals = []
        for arg in args:
            if arg[0] == "range":
                for nm in expand(arg[1], arg[2]):
                    if nm not in cells:
                        continue
                    v = eval_cell(nm)
                    if isinstance(v, str):
                        return v
                    vals.append(v)
            else:
                v = ev(arg)
                if isinstance(v, str):
                    return v
                vals.append(v)
        if not vals or fn == "SUM":
            return sum(vals)
        if fn == "MIN":
            return min(vals)
        return max(vals)

    return {name: eval_cell(name) for name in cells}
